checker_details.tests:
from solution import add_months

def test_basic():
    assert add_months('2026-01-15', 1) == '2026-02-15'

def test_end_of_month_short():
    assert add_months('2026-01-31', 1) == '2026-02-28'

def test_last_day_feb_to_march():
    assert add_months('2026-02-28', 1) == '2026-03-31'

def test_last_day_feb_leap_to_march():
    assert add_months('2024-02-29', 1) == '2024-03-31'

def test_last_day_30_to_31():
    assert add_months('2026-04-30', 1) == '2026-05-31'

def test_not_last_day_30_stays():
    assert add_months('2026-03-30', 1) == '2026-04-30'

def test_day_30_to_feb():
    assert add_months('2026-01-30', 1) == '2026-02-28'

def test_leap_target():
    assert add_months('2026-01-31', 25) == '2028-02-29'

def test_zero():
    assert add_months('2026-02-28', 0) == '2026-02-28'

def test_negative():
    assert add_months('2026-03-31', -1) == '2026-02-28'

def test_negative_cross_year():
    assert add_months('2026-01-15', -2) == '2025-11-15'

def test_forward_cross_year():
    assert add_months('2025-11-30', 3) == '2026-02-28'

def test_large_negative():
    assert add_months('2026-01-31', -24) == '2024-01-31'

def test_large_positive_12():
    assert add_months('2026-06-15', 12) == '2027-06-15'

def test_feb28_nonleap_not_last_in_leap():
    assert add_months('2026-02-28', 12) == '2027-02-28'
    assert add_months('2027-02-28', 12) == '2028-02-29'

def test_leap_feb28_not_last():
    assert add_months('2024-02-28', 1) == '2024-03-28'

def test_padding_year():
    assert add_months('0999-01-15', 1) == '0999-02-15'

def test_december_boundary():
    assert add_months('2026-12-31', 1) == '2027-01-31'
    assert add_months('2026-01-31', -1) == '2025-12-31'
